/**
 * Variant registry.
 *
 * Every variant maps a cell of the grid to a *phase* in `[0, 1]` (a fraction of
 * one animation cycle) or to `null`, meaning the cell is not part of the shape
 * and should render as inactive. Phases are resolution independent, so the same
 * variant looks consistent on a 3x3 or on a 12x12 grid.
 */

import {
  DIGIT_KEYS,
  DIGIT_PATTERNS,
  LETTER_KEYS,
  LETTER_PATTERNS,
  SYMBOL_KEYS,
  SYMBOL_PATTERNS,
  getMask,
  normalizeMask,
  type DigitName,
  type GridMask,
  type LetterName,
  type MaskSet,
  type SymbolName,
} from "./patterns"

