export type GridLoaderCategory = (typeof GRID_LOADER_CATEGORIES)[number]["key"]

// ---------------------------------------------------------------------------
// Cell context
// ---------------------------------------------------------------------------

export interface CellContext {
  /** Row index. */
  r: number
  /** Column index. */
  c: number
  /** Flat index (`r * n + c`). */
  i: number
  /** Grid size. */
  n: number
  /** `n - 1`. */
  max: number
  /** Center coordinate, `(n - 1) / 2`. */
  mid: number
  /** `n * n`. */
  total: number
  /** Horizontal offset from the center. */
  dx: number
  /** Vertical offset from the center. */
  dy: number
  /** Row position normalized to `[0, 1]`. */
  rowN: number
  /** Column position normalized to `[0, 1]`. */
  colN: number
  /** Euclidean distance to the center, normalized to `[0, 1]`. */
  dist: number
  /** Chebyshev (square ring) distance, normalized to `[0, 1]`. */
  cheb: number
  /** Manhattan (diamond) distance, normalized to `[0, 1]`. */
  manh: number
  /** Angle around the center, normalized to `[0, 1)`. */
  angle: number
  /** Index of the square ring the cell belongs to (0 = outer border). */
  ring: number
  /** Ring index normalized to `[0, 1]`. */
  ringN: number
  /** Position along the cell's ring, normalized to `[0, 1)`. */
  ringPos: number
  /** Deterministic pseudo random value in `[0, 1)`. */
  rand: number
  /** A second, independent pseudo random value in `[0, 1)`. */
  rand2: number
}

export type PhaseFn = (cell: CellContext) => number | null

export interface VariantSpec {
  label: string
  category: GridLoaderCategory
  /** Per-cell phase. Ignored when `phases` is provided. */
  phase: PhaseFn
  /** Whole-grid phases, for variants that depend on a global ordering. */
  phases?: (n: number) => (number | null)[]
  /** Minimum grid size that still renders a meaningful shape. */
  minGrid?: number
}

// ---------------------------------------------------------------------------
// Math helpers
// ---------------------------------------------------------------------------

const TAU = Math.PI * 2

function hash(x: number, seed = 0): number {
  let h = Math.imul(x + 1, 374761393) + Math.imul(seed + 1, 668265263)
  h = Math.imul(h ^ (h >>> 13), 1274126177)
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296
}

const frac = (v: number) => ((v % 1) + 1) % 1
const ratio = (v: number, d: number) => (d > 0 ? v / d : 0)
const near = (a: number, b: number, tolerance = 0.5) => Math.abs(a - b) <= tolerance

function ringInfo(r: number, c: number, max: number) {
  const ring = Math.min(r, c, max - r, max - c)
  const side = max - ring * 2
  if (side <= 0) return { ring, pos: 0, len: 1 }
  const rr = r - ring
  const cc = c - ring
  let pos: number
  if (rr === 0) pos = cc
  else if (cc === side) pos = side + rr
  else if (rr === side) pos = side * 2 + (side - cc)
  else pos = side * 3 + (side - rr)
  return { ring, pos, len: side * 4 }
}

export function createCellContext(i: number, n: number): CellContext {
  const r = Math.floor(i / n)
  const c = i % n
  const max = n - 1
  const mid = max / 2
  const dx = c - mid
  const dy = r - mid
  const maxRadius = Math.sqrt(2) * mid || 1
  const { ring, pos, len } = ringInfo(r, c, max)
  return {
    r,
    c,
    i,
    n,
    max,
    mid,
    total: n * n,
    dx,
    dy,
    rowN: ratio(r, max),
    colN: ratio(c, max),
    dist: Math.min(1, Math.sqrt(dx * dx + dy * dy) / maxRadius),
    cheb: ratio(Math.max(Math.abs(dx), Math.abs(dy)), mid),
    manh: ratio(Math.abs(dx) + Math.abs(dy), max),
    angle: frac((Math.atan2(dy, dx) + Math.PI) / TAU),
    ring,
    ringN: ratio(ring, Math.floor(max / 2)),
    ringPos: ratio(pos, len),
    rand: hash(i),
    rand2: hash(i, 977),
  }
}

